def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    if len(cmd) == 0:
        return cmd
    if os.name == "nt":
        if cmd[0].startswith("#!"):
            cmd = cmd[1:]
        if cmd[0].endswith(".exe"):
            cmd = cmd[:-4]
    return cmd

