def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(func):
        cache = {}
        hits = misses = 0
        lock = threading.Lock()

        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            key = (args, frozenset(kwargs.items())) if typed else args
            with lock:
                now = timer()
                try:
                    value, expire_at = cache[key]
                    if now < expire_at:
                        hits += 1
                        return value
                    else:
                        misses += 1
                        raise KeyError
                except KeyError:
                    misses += 1
                    value = func(*args, **kwargs)
                    cache[key] = (value, now + ttl)
                    if len(cache) > maxsize:
                        cache.popitem(last=False)
                    return value

        def cache_info():
            with lock:
                return {
                    "hits": hits,
                    "misses": misses,
                    "maxsize": maxsize,
                    "size": len(cache),
                }

        wrapper.cache_info = cache_info
        return wrapper

    return decorator

def mru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        mru = []
        def wrapper(*args, **kwargs):
            key = (args, frozenset(kwargs.items())) if typed else args
            if key in cache:
                mru.remove(key)
                mru.append(key)
                return cache[key]
            else:
                result = func(*args, **kwargs)
                cache[key] = result
                mru.append(key)
                if len(mru) > maxsize:
                    cache.pop(mru.pop(0))
                return result
        return wrapper
    return decorator

