def _update_context(self, context):
    if not isinstance(context, dict):
        raise TypeError("context must be a dictionary")
    if "error" not in context:
        context["error"] = {}
    if "value" not in context:
        context["value"] = {}
    for field in self.fields:
        if field.startswith("error_"):
            error_name = field[6:]
            if error_name not in context["error"]:
                context["error"][error_name] = {}
            context["error"][error_name]["index"] = self.fields.index(field)
        else:
            context["value"][field] = self.fields[field]
    return context

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    if not isinstance(bins, list):
        raise TypeError("bins must be a list")
    if not isinstance(edges, list):
        raise TypeError("edges must be a list")
    if len(bins) != len(edges) - 1:
        raise ValueError("bins and edges must have the same length")
    if not all(isinstance(x, (int, float)) for x in bins):
        raise TypeError("bins must contain only integers or floats")
    if not all(isinstance(x, (int, float)) for x in edges):
        raise TypeError("edges must contain only integers or floats")
    if not all(x >= 0 for x in bins):
        raise ValueError("bins must contain only non-negative values")
    if not all(x >= 0 for x in edges):
        raise ValueError("edges must contain only non-negative values")
    if not all(x < y for x, y in zip(edges, edges[1:])):
        raise ValueError("edges must be strictly increasing")

    return sum(bins) * (edges[-1] - edges[0]) / len(bins)

