def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    observer_schema = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            observer_schema[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            observer_schema[key] = [generate_default_observer_schema_dict(item, first_level=False) for item in value]
        else:
            observer_schema[key] = None
    if first_level:
        for key in ["apiVersion", "kind", "metadata", "spec"]:
            if key in manifest_dict:
                observer_schema[key] = manifest_dict[key]
    return observer_schema

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    for field in observer_schema:
        if field not in last_applied_manifest:
            last_applied_manifest[field] = response[field]
        elif isinstance(last_applied_manifest[field], list):
            last_applied_manifest[field] = update_last_applied_manifest_list_from_resp(last_applied_manifest[field], observer_schema[field], response[field])
        elif isinstance(last_applied_manifest[field], dict):
            last_applied_manifest[field] = update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], observer_schema[field], response[field])
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field in observer_schema:
        if field not in response:
            raise KeyError(f"Observed field {field} not present in response")
        if field not in last_applied_manifest:
            last_applied_manifest[field] = response[field]
        elif isinstance(last_applied_manifest[field], dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], observer_schema[field], response[field])
        elif isinstance(last_applied_manifest[field], list):
            update_last_applied_manifest_list_from_resp(last_applied_manifest[field], observer_schema[field], response[field])
        else:
            last_applied_manifest[field] = response[field]
    return last_applied_manifest

def format(self, sql, params):
    if isinstance(params, dict):
        # Convert named parameters to ordinal parameters
        params = list(params.values())
    elif isinstance(params, list):
        # Convert ordinal parameters to named parameters
        params = {i: param for i, param in enumerate(params)}
    else:
        raise ValueError("Invalid parameter type")

    # Replace in-style parameters with out-style parameters
    sql = sql.replace("?", ":{}")

    return sql, params

def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    formatted_sql = sql
    out_params = []
    for params in many_params:
        if isinstance(params, Mapping):
            out_params.append(self._format_mapping(params))
        elif isinstance(params, Sequence):
            out_params.append(self._format_sequence(params))
        else:
            raise ValueError("Invalid parameter type: {}".format(type(params)))
    return formatted_sql, out_params

