def check_digests_present_and_used(self, manifest_files, digests_used):
    for manifest_file in manifest_files:
        with open(manifest_file, "r") as f:
            manifest = json.load(f)
            for digest in manifest["digests"]:
                if digest not in digests_used:
                    raise ValueError(f"Digest {digest} is not used in any file")
                if digest not in self.digests:
                    raise ValueError(f"Digest {digest} is not present in the repository")
    return True

def validate_as_prior_version(self, prior):
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator object")
    if self.version < prior.version:
        raise ValueError("prior version must be less than or equal to current version")
    if self.version == prior.version:
        raise ValueError("prior version must be less than current version")
    if self.inventory != prior.inventory:
        raise ValueError("inventory must be the same for both prior and current versions")
    if self.timestamp < prior.timestamp:
        raise ValueError("timestamp must be greater than or equal to prior timestamp")
    if self.timestamp == prior.timestamp:
        raise ValueError("timestamp must be greater than prior timestamp")
    if self.checksum != prior.checksum:
        raise ValueError("checksum must be the same for both prior and current versions")
    if self.signature != prior.signature:
        raise ValueError("signature must be the same for both prior and current versions")
    return True

def get_logical_path_map(inventory, version):
    logical_path_map = {}
    for state in inventory:
        if state["version"] == version:
            for logical_path in state["logical_paths"]:
                if logical_path not in logical_path_map:
                    logical_path_map[logical_path] = set()
                logical_path_map[logical_path].add(state["content_file"])
    return logical_path_map

