def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    try:
        with ZipFile(zip_path, 'r') as zip_file:
            file_names = zip_file.namelist()
            file_data = {}
            for file_name in file_names:
                if file_name.endswith('.xml'):
                    file_data[file_name] = zip_file.read(file_name).decode('utf-8')
            return file_data
    except FileNotFoundError:
        raise ValueError(f"File not found at {zip_path}")
    except zipfile.BadZipFile:
        raise ValueError(f"Invalid zip file at {zip_path}")
    except UnicodeDecodeError:
        raise ValueError(f"Unable to decode file at {zip_path}")

