def absorb(self, args):
    new_args = []
    for arg in args:
        if arg.is_and():
            if arg.left.is_equal(arg.right):
                new_args.append(arg.left)
            elif arg.right.is_equal(arg.left):
                new_args.append(arg.right)
            else:
                new_args.append(arg)
        elif arg.is_or():
            if arg.left.is_equal(arg.right):
                new_args.append(arg.left)
            elif arg.right.is_equal(arg.left):
                new_args.append(arg.right)
            else:
                new_args.append(arg)
        else:
            new_args.append(arg)
    return new_args

