def validate_version_inventories(self, version_dirs):
    # Check if version_dirs is a list or tuple
    if not isinstance(version_dirs, (list, tuple)):
        raise ValueError("version_dirs must be a list or tuple")

    # Check if version_dirs is not empty
    if not version_dirs:
        raise ValueError("version_dirs must not be empty")

    # Check if version_dirs is in version sequence (1, 2, 3...)
    for i, version_dir in enumerate(version_dirs):
        if i != int(version_dir.split("_")[-1]) - 1:
            raise ValueError(f"version_dir {version_dir} is not in version sequence")

    # Check if each version has an inventory
    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, "inventory.json")
        if not os.path.exists(inventory_path):
            raise ValueError(f"inventory.json not found in {version_dir}")

    # Check if any content digests are different from those in the root inventory
    root_inventory_path = os.path.join(self.root_dir, "inventory.json")
    with open(root_inventory_path, "r") as f:
        root_inventory = json.load(f)
    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, "inventory.json")
        with open(inventory_path, "r") as f:
            inventory = json.load(f)
        for key, value in inventory.items():
            if key not in root_inventory or value != root_inventory[key]:
                raise ValueError(f"content digest {key} is different from root inventory")

    # Return the list of version directories
    return version_dirs

def find_path_type(path):
    if not os.path.isdir(path):
        return "not a directory"
    if os.path.isfile(path):
        return "file"
    if os.path.isfile(os.path.join(path, "0=*")):
        return "root"
    if os.path.isfile(os.path.join(path, "0=*", "inventory")):
        return "object"
    return "other"

