def paging(response, max_results):
    if not isinstance(response, list):
        raise ValueError("Invalid response type. Expected list, got {}".format(type(response)))
    if not isinstance(max_results, int):
        raise ValueError("Invalid max_results type. Expected int, got {}".format(type(max_results)))
    if max_results <= 0:
        raise ValueError("Invalid max_results value. Expected positive integer, got {}".format(max_results))

    for i in range(0, len(response), max_results):
        yield response[i:i + max_results]

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not size:
        raise ValueError("Invalid input size")
    size = size.upper()
    if size[-1] in ["K", "M", "G", "T"]:
        return int(float(size[:-1]) * {"K": 1000, "M": 1000000, "G": 1000000000, "T": 1000000000000}[size[-1]])
    else:
        return int(size)

def _dictsum(dicts):
    result = {}
    for d in dicts:
        for k, v in d.items():
            if k not in result:
                result[k] = v
            else:
                result[k] += v
    return result

def _replace_url_args(url, url_args):
