def string_to_int(string: str, alphabet: List[str]) -> int:
    if not isinstance(string, str):
        raise ValueError("Input must be a string")
    if not isinstance(alphabet, list):
        raise ValueError("Alphabet must be a list")
    if len(alphabet) == 0:
        raise ValueError("Alphabet cannot be empty")

    result = 0
    for i, char in enumerate(string):
        if char not in alphabet:
            raise ValueError(f"Character '{char}' is not in the alphabet")
        result += alphabet.index(char) * (len(alphabet) ** i)

    return result

def get_repo_archive(url: str, destination_path: Path) -> Path:
    try:
        response = requests.get(url)
        if response.status_code == 200:
            with open(destination_path, "wb") as f:
                f.write(response.content)
            with tarfile.open(destination_path, "r:gz") as tar:
                tar.extractall(destination_path)
            return destination_path
        else:
            raise Exception(f"Failed to download archive: {response.status_code}")
    except Exception as e:
        raise Exception(f"Failed to extract archive: {e}")

