def protocol_handlers(cls, protocol_version=None):
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("Protocol version must be passed in a tuple")

    if protocol_version is None:
        return {version: cls.protocol_handlers[version] for version in cls.protocol_handlers}

    if protocol_version not in cls.protocol_handlers:
        return {}

    return {protocol_version: cls.protocol_handlers[protocol_version]}

def _get_seq_with_type(seq, bufsize=None):
    if isinstance(seq, str):
        return seq, str
    elif isinstance(seq, bytes):
        return seq, bytes
    elif isinstance(seq, bytearray):
        return seq, bytearray
    elif isinstance(seq, memoryview):
        return seq, memoryview
    elif isinstance(seq, list):
        return seq, list
    elif isinstance(seq, tuple):
        return seq, tuple
    elif isinstance(seq, range):
        return seq, range
    elif isinstance(seq, set):
        return seq, set
    elif isinstance(seq, frozenset):
        return seq, frozenset
    elif isinstance(seq, dict):
        return seq, dict
    elif isinstance(seq, collections.abc.Sequence):
        return seq, collections.abc.Sequence
    elif isinstance(seq, collections.abc.Set):
        return seq, collections.abc.Set
    elif isinstance(seq, collections.abc.Mapping):
        return seq, collections.abc.Mapping
    else:
        raise TypeError("unsupported sequence type")

def scale(self, other=None, recompute=False):
    if other is None:
        if self.scale is None or recompute:
            self.scale = self.integral()
        return self.scale
    else:
        if self.scale == 0:
            raise LenaValueError("Histograms with scale equal to zero can't be rescaled.")
        self.scale = other
        return self.scale

def scale(self, other=None):
    if other is None:
        return self.scale
    if self.scale == 0:
        raise LenaValueError("Cannot rescale graph with unknown or zero scale")
    self.scale = other
    for field in self.fields:
        if field.endswith("_error"):
            field_name = field[:-6]
            setattr(self, field_name, getattr(self, field_name) * other)
        else:
            setattr(self, field, getattr(self, field) * other)
    return self.scale

def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if not isinstance(hist, Histogram):
        raise TypeError("hist must be a Histogram")
    if make_value is not None and not callable(make_value):
        raise TypeError("make_value must be a callable")
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be 'left', 'right' or 'middle'")
    if not isinstance(field_names, tuple) or len(field_names) != hist.dimension:
        raise ValueError("field_names must be a tuple of length equal to the histogram dimension")
    if scale is not None and not isinstance(scale, bool):
        raise TypeError("scale must be a boolean")

    graph = Graph(field_names=field_names)
    for bin_ in hist.bins:
        if make_value is None:
            value = bin_.content
        else:
            value = make_value(bin_)
        if get_coordinate == "left":
            coordinate = bin_.left
        elif get_coordinate == "right":
            coordinate = bin_.right
        else:
            coordinate = (bin_.left + bin_.right) / 2
        graph.add_point(coordinate, value)

    if scale is not None:
        graph.scale = hist.scale if scale else None

    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    try:
        if not tentative and not iface.providedBy(candidate):
            raise zope.interface.Invalid("Candidate does not provide the interface")
        for name, spec in iface.namesAndDescriptions():
            if name not in candidate:
                raise zope.interface.Invalid("Candidate does not define the required method {}".format(name))
            if spec.signature is not None and spec.signature != candidate[name].__signature__:
                raise zope.interface.Invalid("Candidate method {} has an incorrect signature".format(name))
        for name, spec in iface.namesAndDescriptions():
            if name not in candidate:
                raise zope.interface.Invalid("Candidate does not define the required attribute {}".format(name))
        return True
    except zope.interface.Invalid as e:
        raise e

def verifyObject(iface, candidate, tentative=False):
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid("Candidate does not claim to provide the interface")

    for name, method in iface.getMethods():
        if not hasattr(candidate, name):
            raise zope.interface.Invalid("Candidate does not define method {}".format(name))
        if not callable(getattr(candidate, name)):
            raise zope.interface.Invalid("Method {} is not callable".format(name))

    for name, attribute in iface.getAttributes():
        if not hasattr(candidate, name):
            raise zope.interface.Invalid("Candidate does not define attribute {}".format(name))

    return True

