def determineMetaclass(bases, explicit_mc=None):
    if explicit_mc is not None:
        return explicit_mc
    else:
        for base in bases:
            if hasattr(base, "__metaclass__"):
                return base.__metaclass__
        return type

def pop(self, key, default=__marker):
    try:
        value = self[key]
        del self[key]
        return value
    except KeyError:
        if default is not __marker:
            return default
        else:
            raise

def popitem(self):
    if len(self) == 0:
        raise KeyError("Cache is empty")

    min_freq = min(self.freqs.values())
    for key, freq in self.freqs.items():
        if freq == min_freq:
            del self.freqs[key]
            return key, self.cache.pop(key)

def popitem(self):
    if len(self) == 0:
        raise KeyError("Cache is empty")
    else:
        key = self._order.pop()
        value = self._cache.pop(key)
        return (key, value)

def popitem(self):
    if len(self) == 0:
        raise KeyError("popitem(): dictionary is empty")
    key = next(reversed(self))
    value = self.pop(key)
    return (key, value)

def popitem(self):
    if len(self) == 0:
        raise KeyError("popitem(): dictionary is empty")
    key = random.choice(list(self.keys()))
    value = self.pop(key)
    return (key, value)

def fromutc(self, dt):
    if not isinstance(dt, datetime.datetime):
        raise TypeError("dt must be a datetime.datetime object")
    if not dt.tzinfo:
        raise ValueError("dt must be a timezone-aware datetime object")
    if not isinstance(self.tz, datetime.tzinfo):
        raise TypeError("self.tz must be a datetime.tzinfo object")
    if self.tz == dt.tzinfo:
        return dt
    # Convert dt to UTC
    utc_dt = dt.astimezone(datetime.timezone.utc)
    # Convert utc_dt to self.tz
    return utc_dt.astimezone(self.tz)

def default_tzinfo(dt, tzinfo):
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=tzinfo)
    return dt

