    if not isinstance(after, bytes):
        raise TypeError("'after' must be of type 'bytes'")
    self.before = before
    self.after = after

def identify_request(request: RequestType):
    if request.message.startswith("Diaspora"):
        return True
    elif request.message.startswith("Private"):
        return True
    elif request.payload.startswith("Legacy"):
        return True
    else:
        return False

def identify_request(request: RequestType) -> bool:
    try:
        if request.headers["User-Agent"].startswith("Mozilla/5.0 (X11; Linux x86_64; rv:60.0) Gecko/20100101 Firefox/60.0"):
            return True
        elif request.headers["User-Agent"].startswith("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/74.0.3729.169 Safari/537.36"):
            return True
        else:
            return False
    except KeyError:
        return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    return dt.strftime("%Y-%m-%dT%H:%M:%S.%fZ")

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    code_block = False
    for word in text.split():
        if word == "```":
            code_block = not code_block
            continue
        if code_block:
            continue
        if word.startswith("#"):
            tags.add(word[1:])
    if replacer:
        text = " ".join(replacer(word) if word.startswith("#") else word for word in text.split())
    return tags, text

